ExternalServiceRegistration.schema:
{
  "openapi": "3.0.0",
  "info": {
    "title": "QuickBooks Online Query API (read-only)",
    "version": "1.0.0"
  },
  "servers": [
    {
      "url": "https://sandbox-quickbooks.api.intuit.com"
    }
  ],
  "paths": {
    "/v3/company/{realmId}/query": {
      "get": {
        "operationId": "runQuery",
        "summary": "Run a read-only QuickBooks query",
        "parameters": [
          {
            "name": "realmId",
            "in": "path",
            "required": true,
            "schema": {
              "type": "string"
            }
          },
          {
            "name": "query",
            "in": "query",
            "required": true,
            "schema": {
              "type": "string"
            }
          },
          {
            "name": "minorversion",
            "in": "query",
            "required": false,
            "schema": {
              "type": "string"
            }
          },
          {
            "name": "Accept",
            "in": "header",
            "required": false,
            "schema": {
              "type": "string",
              "default": "application/json"
            }
          }
        ],
        "responses": {
          "200": {
            "description": "OK",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "time": {
                      "type": "string"
                    },
                    "QueryResponse": {
                      "type": "object",
                      "properties": {
                        "startPosition": {
                          "type": "integer"
                        },
                        "maxResults": {
                          "type": "integer"
                        },
                        "totalCount": {
                          "type": "integer"
                        },
                        "Customer": {
                          "type": "array",
                          "items": {
                            "type": "object",
                            "properties": {
                              "Id": {
                                "type": "string"
                              },
                              "DisplayName": {
                                "type": "string"
                              },
                              "CompanyName": {
                                "type": "string"
                              },
                              "Active": {
                                "type": "boolean"
                              },
                              "Balance": {
                                "type": "number"
                              },
                              "PrimaryEmailAddr": {
                                "type": "object",
                                "properties": {
                                  "Address": {
                                    "type": "string"
                                  }
                                }
                              }
                            }
                          }
                        },
                        "Invoice": {
                          "type": "array",
                          "items": {
                            "type": "object",
                            "properties": {
                              "Id": {
                                "type": "string"
                              },
                              "DocNumber": {
                                "type": "string"
                              },
                              "TxnDate": {
                                "type": "string"
                              },
                              "DueDate": {
                                "type": "string"
                              },
                              "TotalAmt": {
                                "type": "number"
                              },
                              "Balance": {
                                "type": "number"
                              },
                              "PrivateNote": {
                                "type": "string"
                              },
                              "CustomerRef": {
                                "type": "object",
                                "properties": {
                                  "value": {
                                    "type": "string"
                                  },
                                  "name": {
                                    "type": "string"
                                  }
                                }
                              }
                            }
                          }
                        },
                        "Payment": {
                          "type": "array",
                          "items": {
                            "type": "object",
                            "properties": {
                              "Id": {
                                "type": "string"
                              },
                              "TxnDate": {
                                "type": "string"
                              },
                              "TotalAmt": {
                                "type": "number"
                              },
                              "UnappliedAmt": {
                                "type": "number"
                              },
                              "PaymentRefNum": {
                                "type": "string"
                              },
                              "CustomerRef": {
                                "type": "object",
                                "properties": {
                                  "value": {
                                    "type": "string"
                                  },
                                  "name": {
                                    "type": "string"
                                  }
                                }
                              }
                            }
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}
